import java.io.*;
public class JVocabulary1 {
	public static void main(String[] args) {
		JVocabulary1 v1 = new JVocabulary1();
		ArrayList<String> lst = v1.getWords("test1.txt");
		System.out.println("palabras = " + lst);
	}
	//Paso 1: Definir el metodo que crea una lista de palabras desde un archivo
	public ArrayList<String> getWords(String fileName) {
		//Paso 1.1: Crear una lista vacia para almacenar las palabras
		ArrayList<String> words = new ArrayList<String>();
		//Paso 1.2: Encerrar el codigo que puede lanzar una excepcion dentro del bloque try
		try {
			//Paso 1.2.1: Envolver un BufferedReader alrededor de un FileReader
			FileReader fr = new FileReader(fileName); 
			BufferedReader br = new BufferedReader(fr); 
			//Paso 1.2.2: Usar el objeto BufferedReader para leer una linea a la vez
			String line = null;
			while ( ( line = br.readLine() ) != null) {
				//Separar la linea en palabras, ignorando el uso de mayusculas y minusculas
				String[] tokens = line.toLowerCase().split(" ");
				//Agregar cada palabra de la linea a la lista
				for (String token : tokens) {
					words.add(token);
				}
			}
			//Paso 1.2.3: Cerrar el objeto BufferedReader adjunto al archivo
			br.close();
		//Paso 1.3: Manejar todas las posibles excepciones que pueden ser lanzadas en el bloque try
		} catch (FileNotFoundException ex) {
			System.out.println("Archivo no encontrado");
		} catch (IOException ex ) {
			System.out.println("Problema con el archivo!");
		}
		//Paso 1.4: devolver la lista
		return words;
	}
}

